SELECT DATE_FORMAT(hire_date, 'yyyy-MM') hire_month, job_title, ROUND(STDDEV(salary), 2) stddev_salary, SORT_ARRAY(COLLECT_SET(level)) level_list, ROUND((100 * SUM(CASE WHEN level = 'L3' THEN 1 ELSE 0 END)) / COUNT(*), 1) pct_l3 FROM employees WHERE (manager_id IN (6, 31, 34) AND dept_id IN (7, 23, 29, 37)) OR MONTH(hire_date) IN (5, 6, 9) GROUP BY hire_month, job_title ORDER BY pct_l3 ASC, stddev_salary DESC;
